CREATE TYPE public.app_role AS ENUM ('admin','recepcao');
CREATE TABLE public.user_roles (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL UNIQUE REFERENCES auth.users(id) ON DELETE CASCADE, account_id uuid NOT NULL, role public.app_role NOT NULL);
GRANT SELECT ON public.user_roles TO authenticated; GRANT ALL ON public.user_roles TO service_role;
ALTER TABLE public.user_roles ENABLE ROW LEVEL SECURITY;
INSERT INTO public.user_roles(user_id,account_id,role) SELECT id,id,'admin'::public.app_role FROM auth.users;
CREATE FUNCTION public.account_owner() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT coalesce((SELECT account_id FROM public.user_roles WHERE user_id=auth.uid()),auth.uid()) $$;
CREATE FUNCTION public.has_role(_user_id uuid,_role public.app_role) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_user_id AND role=_role) $$;
REVOKE ALL ON FUNCTION public.account_owner(),public.has_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.account_owner(),public.has_role(uuid,public.app_role) TO authenticated,service_role;
CREATE POLICY "Account roles read" ON public.user_roles FOR SELECT TO authenticated USING (user_id=auth.uid() OR (account_id=public.account_owner() AND public.has_role(auth.uid(),'admin')));
CREATE FUNCTION public.set_member_role(_member uuid,_role public.app_role) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; PERFORM pg_advisory_xact_lock(hashtext(public.account_owner()::text)); IF _member=public.account_owner() AND _role<>'admin' THEN RAISE EXCEPTION 'O titular deve permanecer administrador'; END IF; UPDATE public.user_roles SET role=_role WHERE user_id=_member AND account_id=public.account_owner(); IF NOT FOUND THEN RAISE EXCEPTION 'Usuário não encontrado'; END IF; END $$;
REVOKE ALL ON FUNCTION public.set_member_role(uuid,public.app_role) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.set_member_role(uuid,public.app_role) TO authenticated;
CREATE TABLE public.site_settings (user_id uuid PRIMARY KEY, settings jsonb NOT NULL DEFAULT '{}'::jsonb CHECK (jsonb_typeof(settings)='object'), updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.site_settings TO authenticated; GRANT ALL ON public.site_settings TO service_role; ALTER TABLE public.site_settings ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Settings account read" ON public.site_settings FOR SELECT TO authenticated USING (user_id=public.account_owner());
CREATE POLICY "Settings admin write" ON public.site_settings FOR ALL TO authenticated USING(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin'));
CREATE TRIGGER updated_settings BEFORE UPDATE ON public.site_settings FOR EACH ROW EXECUTE FUNCTION public.set_updated_at();
CREATE TABLE public.message_templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,title text NOT NULL CHECK(length(title) BETWEEN 1 AND 120),message text NOT NULL CHECK(length(message) BETWEEN 1 AND 5000),created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.message_templates TO authenticated; GRANT ALL ON public.message_templates TO service_role; ALTER TABLE public.message_templates ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Templates account read" ON public.message_templates FOR SELECT TO authenticated USING(user_id=public.account_owner());
CREATE POLICY "Templates admin write" ON public.message_templates FOR ALL TO authenticated USING(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin'));
CREATE TABLE public.ical_feeds (id uuid PRIMARY KEY DEFAULT gen_random_uuid(),user_id uuid NOT NULL,room_id uuid NOT NULL REFERENCES public.rooms(id),provider text NOT NULL CHECK(length(provider)<=100),import_url text NOT NULL DEFAULT '' CHECK(length(import_url)<=2000),export_token uuid NOT NULL DEFAULT gen_random_uuid() UNIQUE,active boolean NOT NULL DEFAULT true,last_synced_at timestamptz,last_error text,created_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT,INSERT,UPDATE,DELETE ON public.ical_feeds TO authenticated; GRANT ALL ON public.ical_feeds TO service_role; ALTER TABLE public.ical_feeds ENABLE ROW LEVEL SECURITY;
CREATE POLICY "Feeds admin" ON public.ical_feeds FOR ALL TO authenticated USING(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin')) WITH CHECK(user_id=public.account_owner() AND public.has_role(auth.uid(),'admin') AND EXISTS(SELECT 1 FROM public.rooms WHERE id=room_id AND user_id=public.account_owner()));
ALTER TABLE public.reservations ADD COLUMN import_feed_id uuid REFERENCES public.ical_feeds(id) ON DELETE RESTRICT, ADD COLUMN external_uid text;
CREATE UNIQUE INDEX reservations_import_uid ON public.reservations(import_feed_id,external_uid) WHERE import_feed_id IS NOT NULL;
CREATE FUNCTION public.apply_ical_events(_feed uuid,_events jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE f public.ical_feeds; e jsonb; n integer:=0; BEGIN SELECT * INTO f FROM public.ical_feeds WHERE id=_feed FOR UPDATE; IF NOT FOUND OR f.user_id<>public.account_owner() OR NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Sem permissão'; END IF; IF jsonb_typeof(_events)<>'array' OR jsonb_array_length(_events)>1000 THEN RAISE EXCEPTION 'Calendário inválido'; END IF; FOR e IN SELECT * FROM jsonb_array_elements(_events) LOOP INSERT INTO public.reservations(user_id,room_id,guest_name,check_in,check_out,status,source,import_feed_id,external_uid) VALUES(f.user_id,f.room_id,'Bloqueio externo · '||f.provider,(e->>'start')::date,(e->>'end')::date,'confirmada','iCal · '||f.provider,f.id,e->>'uid') ON CONFLICT(import_feed_id,external_uid) WHERE import_feed_id IS NOT NULL DO UPDATE SET check_in=EXCLUDED.check_in,check_out=EXCLUDED.check_out,status='confirmada'; n:=n+1; END LOOP; UPDATE public.reservations SET status='cancelada' WHERE import_feed_id=f.id AND status IN('confirmada','pre_reserva') AND NOT EXISTS(SELECT 1 FROM jsonb_array_elements(_events) item WHERE item->>'uid'=external_uid); UPDATE public.ical_feeds SET last_synced_at=now(),last_error=null WHERE id=f.id; RETURN n; END $$;
REVOKE ALL ON FUNCTION public.apply_ical_events(uuid,jsonb) FROM PUBLIC; GRANT EXECUTE ON FUNCTION public.apply_ical_events(uuid,jsonb) TO authenticated;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['rooms','reservations','products','product_ingredients','ingredients','orders','order_items','stock_movements'] LOOP EXECUTE format('CREATE POLICY "Team operational read" ON public.%I FOR SELECT TO authenticated USING(user_id=public.account_owner())',t); END LOOP; FOREACH t IN ARRAY ARRAY['rooms','reservations','orders','order_items','stock_movements'] LOOP EXECUTE format('CREATE POLICY "Team operational write" ON public.%I FOR ALL TO authenticated USING(user_id=public.account_owner()) WITH CHECK(user_id=public.account_owner())',t); END LOOP; END $$;
CREATE POLICY "Media public read" ON storage.objects FOR SELECT TO anon,authenticated USING(bucket_id='site-gallery');
CREATE POLICY "Media admin insert" ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='site-gallery' AND (storage.foldername(name))[1]=public.account_owner()::text AND public.has_role(auth.uid(),'admin'));
CREATE POLICY "Media admin delete" ON storage.objects FOR DELETE TO authenticated USING(bucket_id='site-gallery' AND (storage.foldername(name))[1]=public.account_owner()::text AND public.has_role(auth.uid(),'admin'));